* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; font-size: 16px; color: #172a3a; background: #eaf0ed; }
body { min-height: 100vh; margin: 0; padding: 40px 16px; display: grid; place-items: center; background-color: #eaf0ed; background-image: radial-gradient(#c7d6d0 1.5px, transparent 1.5px); background-size: 22px 22px; }
.card { width: min(100%, 500px); padding: 34px 36px 22px; border: 3px solid #172a3a; border-radius: 10px; background: #fffdf7; box-shadow: 8px 8px 0 #172a3a; }
.header { text-align: center; }
.pixel-clock { width: 48px; height: 48px; margin: 0 auto 18px; display: grid; grid-template-columns: repeat(2, 1fr); gap: 4px; padding: 5px; border: 3px solid #172a3a; background: #f4c95d; transform: rotate(-3deg); }
.pixel-clock span { background: #172a3a; }
.pixel-clock span:nth-child(2), .pixel-clock span:nth-child(3) { background: #fffdf7; }
.eyebrow, .sort-note { color: #54736d; font-size: .75rem; font-weight: 800; letter-spacing: .13em; }
.eyebrow { margin: 0 0 6px; }
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.35rem); line-height: 1.15; letter-spacing: -.04em; }
.subtitle { margin: 8px 0 22px; color: #58706f; }
.summary { min-height: 48px; margin-bottom: 22px; padding: 10px 14px; display: flex; align-items: center; justify-content: center; gap: 9px; border: 2px solid #cbd9d1; border-radius: 6px; background: #edf4ef; color: #29473f; }
.summary strong { font-size: 1.15rem; }
.summary-dot { width: 10px; height: 10px; border-radius: 50%; background: #4f9875; box-shadow: 0 0 0 3px #d3e8d9; }
#alarm-form { display: grid; grid-template-columns: 1fr 1.3fr; gap: 14px 12px; }
.time-fields { display: flex; align-items: end; gap: 9px; }
.field { min-width: 0; display: grid; gap: 6px; }
.field label { font-size: .9rem; font-weight: 700; }
.field label span { color: #71817c; font-weight: 500; }
input { width: 100%; min-width: 0; height: 48px; padding: 0 12px; border: 2px solid #cbd9d1; border-radius: 5px; background: #fff; color: #172a3a; font: inherit; }
input::placeholder { color: #98a7a0; }
input:focus-visible, button:focus-visible { outline: 3px solid #df9a36; outline-offset: 3px; }
input[type="number"] { text-align: center; }
.colon { height: 48px; display: flex; align-items: center; font-weight: 800; }
.add-button { grid-column: 1 / -1; min-height: 50px; border: 2px solid #172a3a; border-radius: 5px; background: #f4c95d; color: #172a3a; font: inherit; font-weight: 800; cursor: pointer; box-shadow: 0 3px 0 #172a3a; transition: transform .12s, box-shadow .12s, background .12s; }
.add-button span { font-size: 1.25rem; vertical-align: -1px; }
.add-button:hover { background: #f7d779; }
.add-button:active { transform: translateY(3px); box-shadow: none; }
.alarms-section { margin-top: 30px; }
.section-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding-bottom: 10px; border-bottom: 2px solid #dce5df; }
h2 { margin: 0; font-size: 1.1rem; }
.sort-note { font-size: .65rem; }
.empty-state { margin: 18px 0; color: #71817c; text-align: center; }
.alarm-list { display: grid; gap: 10px; margin: 14px 0 0; padding: 0; list-style: none; }
.alarm-row { min-height: 72px; display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: 12px; padding: 10px 12px; border: 2px solid #dce5df; border-radius: 6px; background: #fff; }
.alarm-row.is-off { background: #f3f5f2; color: #7f8c86; }
.alarm-time { font-size: 1.45rem; font-weight: 800; font-variant-numeric: tabular-nums; letter-spacing: .02em; }
.alarm-label { display: block; max-width: 220px; overflow: hidden; color: #58706f; font-size: .85rem; text-overflow: ellipsis; white-space: nowrap; }
.is-off .alarm-label { color: #87938e; }
.toggle-wrap { display: flex; align-items: center; gap: 7px; font-size: .82rem; font-weight: 700; cursor: pointer; }
.toggle-wrap input { width: 22px; height: 22px; margin: 0; accent-color: #4f9875; cursor: pointer; }
.delete-button { min-width: 40px; min-height: 40px; border: 2px solid transparent; border-radius: 5px; background: transparent; color: #8a514a; font: inherit; font-size: 1.35rem; cursor: pointer; }
.delete-button:hover { border-color: #e4c5bd; background: #fff1eb; }
.delete-button:active { transform: scale(.93); }
footer { margin-top: 26px; color: #84918b; font-size: .8rem; text-align: center; }
@media (max-width: 420px) { body { padding: 22px 14px; } .card { padding: 27px 20px 18px; } #alarm-form { grid-template-columns: 1fr; } .time-fields { max-width: 210px; } .add-button { grid-column: auto; } .alarm-row { gap: 8px; padding: 9px; } .alarm-time { font-size: 1.3rem; } .toggle-wrap { gap: 4px; } .alarm-label { max-width: 150px; } }

const form = document.querySelector('#alarm-form');
const hourInput = document.querySelector('#hour');
const minuteInput = document.querySelector('#minute');
const labelInput = document.querySelector('#label');
const list = document.querySelector('#alarm-list');
const emptyState = document.querySelector('#empty-state');
const enabledCount = document.querySelector('#enabled-count');

let alarms = [];
let nextId = 1;

function render() {
  alarms.sort((a, b) => a.hour * 60 + a.minute - (b.hour * 60 + b.minute));
  list.replaceChildren();
  emptyState.hidden = alarms.length > 0;
  enabledCount.textContent = String(alarms.filter(alarm => alarm.enabled).length);

  for (const alarm of alarms) {
    const item = document.createElement('li');
    item.className = `alarm-row${alarm.enabled ? '' : ' is-off'}`;

    const details = document.createElement('div');
    const time = document.createElement('span');
    time.className = 'alarm-time';
    time.textContent = `${String(alarm.hour).padStart(2, '0')}:${String(alarm.minute).padStart(2, '0')}`;
    details.append(time);
    if (alarm.label) {
      const label = document.createElement('span');
      label.className = 'alarm-label';
      label.textContent = alarm.label;
      details.append(label);
    }

    const toggleLabel = document.createElement('label');
    toggleLabel.className = 'toggle-wrap';
    const toggle = document.createElement('input');
    toggle.type = 'checkbox';
    toggle.checked = alarm.enabled;
    toggle.setAttribute('aria-label', `Alarm ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''} on`);
    toggle.addEventListener('change', () => {
      alarm.enabled = toggle.checked;
      render();
    });
    toggleLabel.append(toggle, document.createTextNode('On'));

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', `Delete alarm ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    remove.addEventListener('click', () => {
      alarms = alarms.filter(entry => entry.id !== alarm.id);
      render();
    });

    item.append(details, toggleLabel, remove);
    list.append(item);
  }
}

form.addEventListener('submit', event => {
  event.preventDefault();
  if (!form.reportValidity()) return;
  alarms.push({
    id: nextId++,
    hour: Number(hourInput.value),
    minute: Number(minuteInput.value),
    label: labelInput.value.trim(),
    enabled: true
  });
  form.reset();
  hourInput.focus();
  render();
});

render();
